INSERT IGNORE INTO `reviews` (`id`, `company_id`, `user_id`, `rating`, `comment`, `author_name`, `source`, `review_date`, `created_at`) VALUES
  ('029606c2-865a-4ace-b3f3-036f03482ddb', '0c0db117-e641-4adc-856f-b517d6aa4bb2', NULL, 5, 'Aqui em São José da Lapa a Auto Limpeza Pro me atendeu super bem. Limparam meu sofá retrátil, eu amei e super indico.', 'Adriene Dias', 'google', '2026-07-03 00:00:00.000', '2026-07-03 00:00:00.000'),
  ('07d295b2-8b7a-4300-818f-e1f297a59214', '0c0db117-e641-4adc-856f-b517d6aa4bb2', NULL, 5, 'Minhas cadeiras ficaram novas como de fábrica. Serviço top!', 'Roger Souza', 'google', '2026-03-10 00:00:00.000', '2026-03-10 00:00:00.000'),
  ('150c5c47-dec0-4774-8b41-20319e5ae672', '0c0db117-e641-4adc-856f-b517d6aa4bb2', NULL, 5, 'Ficou muito bom a higienização do colchão. Em Vespasiano a Auto Limpeza Pro limpou e higienizou, ficou novo.', 'Raimundo Geraldo Ramos', 'google', '2026-06-26 00:00:00.000', '2026-06-26 00:00:00.000'),
  ('1adc50f3-2ed9-48ef-aa30-1d411769eb3c', '0c0db117-e641-4adc-856f-b517d6aa4bb2', NULL, 5, 'Excelente serviço! A Auto Limpeza Pro fez a limpeza do estofado aqui em São José da Lapa e o resultado foi surpreendente. Atendimento pontual, muito profissional e cuidadoso, explicaram todo o processo e deixaram o estofado limpo e cheiroso.', 'Agência Wr-Solução Digital', 'google', '2026-05-10 00:00:00.000', '2026-05-10 00:00:00.000'),
  ('25f471b7-5025-45ca-8aea-d47e17d2e879', '0c0db117-e641-4adc-856f-b517d6aa4bb2', NULL, 5, 'Gostaria de elogiar o excelente serviço de higienização do colchão. O trabalho foi realizado com muito cuidado, atenção aos detalhes e profissionalismo. O colchão ficou muito mais limpo, com aspecto renovado e um cheiro muito agradável.', 'Pry Alves', 'google', '2026-05-10 00:00:00.000', '2026-05-10 00:00:00.000'),
  ('4b96962c-c694-486d-9981-c93ac284e548', '0c0db117-e641-4adc-856f-b517d6aa4bb2', NULL, 5, 'Serviço de primeira, top... Super indico!', 'Bruno Martins Costa', 'google', '2026-02-10 00:00:00.000', '2026-02-10 00:00:00.000'),
  ('5e41a909-9ded-4b8b-87c6-5148a7bbb4a0', '0c0db117-e641-4adc-856f-b517d6aa4bb2', NULL, 5, 'Aqui em Vespasiano fez a limpeza do meu sofá. Super indico.', 'Vanderlucia Ramos', 'google', '2026-06-26 00:00:00.000', '2026-06-26 00:00:00.000'),
  ('6c23bfc5-e356-4dd3-a615-a46057f0ea63', '0c0db117-e641-4adc-856f-b517d6aa4bb2', NULL, 5, 'Muito bom 👍', 'Jonas Oliveira', 'google', '2026-01-10 00:00:00.000', '2026-01-10 00:00:00.000'),
  ('6ca725fa-65f1-4a64-8cab-9af42711cd74', '0c0db117-e641-4adc-856f-b517d6aa4bb2', 'b53e9f43-69a2-4286-8c6c-c576bcdfb9ca', 5, 'Ótima empresa. Recomendo', NULL, 'app', NULL, '2026-07-09 22:30:46.841'),
  ('71f8cc05-75c9-4336-940a-22bd23cbb04f', '0c0db117-e641-4adc-856f-b517d6aa4bb2', NULL, 5, 'Moro no bairro Célvia, em Vespasiano, e contratei a limpeza de sofá. Simplesmente impecável! Tiraram manchas que eu achei que nunca sairiam. Serviço profissional, rápido e com muita atenção aos detalhes. Sem contar o cuidado com o ambiente da casa. Com certeza virei cliente fiel!', 'Gean Conrado', 'google', '2026-06-26 00:00:00.000', '2026-06-26 00:00:00.000'),
  ('7a528362-0843-4da4-802d-76bde8f8952e', '0c0db117-e641-4adc-856f-b517d6aa4bb2', NULL, 5, 'Trabalho de excelência. Deixei meu sofá como novo. Muito obrigada.', 'Rosemeire Mendes', 'google', '2026-06-10 00:00:00.000', '2026-06-10 00:00:00.000'),
  ('7c067627-a2af-4696-862a-25f33d92b6f8', '0c0db117-e641-4adc-856f-b517d6aa4bb2', NULL, 5, 'Super recomendo, William! Meu sofá ficou muito bom e minhas cadeiras super limpas e cheirosas.', 'Taimara Abreu', 'google', '2026-07-05 00:00:00.000', '2026-07-05 00:00:00.000'),
  ('873a6dbf-ffd2-443f-a218-2cddfe875017', '0c0db117-e641-4adc-856f-b517d6aa4bb2', NULL, 5, 'Fiz uma limpeza interna do meu veículo aqui em São José da Lapa e fiquei muito satisfeito com o resultado. O serviço de higienização foi extremamente bem feito, deixando o carro com aparência de novo e um cheiro muito agradável.', 'Mlkmaneiro Tooh', 'google', '2026-06-26 00:00:00.000', '2026-06-26 00:00:00.000'),
  ('9c8665a6-7d11-4e25-bb23-6ee178d243a5', '0c0db117-e641-4adc-856f-b517d6aa4bb2', NULL, 5, 'Aqui no bairro Dom Pedro, em São José da Lapa, foi difícil encontrar um serviço tão bom assim. Meu sofá estava encardido e achei que não teria solução, mas o resultado foi surpreendente. Ficou limpo, higienizado e com aparência de novo. Atendimento excelente do início ao fim. Super recomendo!', 'Savio Júnior', 'google', '2026-06-26 00:00:00.000', '2026-06-26 00:00:00.000'),
  ('a049fe8c-3ad8-4fe4-b3c3-d748656aee13', '0c0db117-e641-4adc-856f-b517d6aa4bb2', NULL, 5, 'Fiz a higienização do meu sofá com o Auto Limpeza Pro aqui em São José da Lapa e fiquei muito satisfeito com o resultado. O sofá parecia limpo, mas na limpeza saiu muita sujeira. O atendimento foi profissional e chegou no horário.', 'Companhiadodryallltda', 'google', '2026-04-10 00:00:00.000', '2026-04-10 00:00:00.000'),
  ('abb959e2-c892-4d1b-98b5-0fdec04ed4ac', '0c0db117-e641-4adc-856f-b517d6aa4bb2', NULL, 5, 'Serviço bem executado e com muito capricho. Recomendo demais!', 'Karoline Martins', 'google', '2026-06-19 00:00:00.000', '2026-06-19 00:00:00.000'),
  ('b384dd81-8af4-49a5-bd92-e058b5747f7f', '0c0db117-e641-4adc-856f-b517d6aa4bb2', NULL, 5, 'Muito bom o serviço, amei ☺️', 'Alice Rodrigues', 'google', '2026-01-10 00:00:00.000', '2026-01-10 00:00:00.000'),
  ('bcf28503-c3e9-4ee5-959a-463dc79db8b4', '0c0db117-e641-4adc-856f-b517d6aa4bb2', NULL, 5, 'Serviço excelente! Fiz a higienização do meu sofá com a Auto Limpeza Pro e o resultado ficou incrível. O estofado voltou a ter cheiro de novo e a equipe foi super atenciosa. Recomendo a todos que procuram limpeza profissional de estofados 👏✨', 'Dalton Winston', 'google', '2025-11-10 00:00:00.000', '2025-11-10 00:00:00.000'),
  ('d19ff35e-b6b4-4449-9d27-a31d6ea3fc98', '0c0db117-e641-4adc-856f-b517d6aa4bb2', NULL, 5, 'Ótimos serviços prestados, meu sofá e cadeira ficaram ótimos. Eu recomendo a Auto Limpeza Pro.', 'William SP', 'google', '2026-07-05 00:00:00.000', '2026-07-05 00:00:00.000'),
  ('d39e37e2-bbd3-4dba-8576-bfbb5eef3e2d', '0c0db117-e641-4adc-856f-b517d6aa4bb2', NULL, 5, 'Chamei a Auto Limpeza Pro para fazer a limpeza do sofá e colchão, e fiquei muito satisfeito. Atendimento rápido, preço justo e resultado impecável. Dá pra ver que é um trabalho feito com capricho e produtos de qualidade. Indico sem medo!', 'Vinicius Fraiha', 'google', '2025-11-10 00:00:00.000', '2025-11-10 00:00:00.000'),
  ('d4ba0994-4bdb-4b8a-a4d5-6e5edc4270d6', '0c0db117-e641-4adc-856f-b517d6aa4bb2', NULL, 5, 'Ótimo serviço de higienização de sofá, atendimento rápido e resultado muito bom. Recomendo em São José da Lapa.', 'Cartão Inteligente API', 'google', '2026-04-10 00:00:00.000', '2026-04-10 00:00:00.000'),
  ('d76eda80-daf2-44c7-8135-8e3e3b15c621', '0c0db117-e641-4adc-856f-b517d6aa4bb2', NULL, 5, 'Excelente.', 'Michelli Diniz', 'google', '2025-11-10 00:00:00.000', '2025-11-10 00:00:00.000'),
  ('d8cf52a2-835d-40ab-8838-659eeddb3716', '0c0db117-e641-4adc-856f-b517d6aa4bb2', NULL, 5, 'A limpeza e higienização do meu carro ficou excelente. Tirou totalmente o odor terrível de urina (depois de um acidente com cachorra) e limpou bancos, carpetes, porta-malas e tudo mais. O carro ficou um brinco. Além do atendimento extremamente gentil e prestativo do William, fez toda a diferença. Sou grato!', 'Shirley Rabelo', 'google', '2026-03-10 00:00:00.000', '2026-03-10 00:00:00.000'),
  ('f267be12-382a-465e-be02-e8876ca0b316', '0c0db117-e641-4adc-856f-b517d6aa4bb2', NULL, 5, 'Serviço impecável! Limpeza muito bem feita e muito caprichosa. Amei o resultado e com certeza recomendo! ✨👏', 'Juliana', 'google', '2026-05-10 00:00:00.000', '2026-05-10 00:00:00.000'),
  ('f8c2dea8-021e-4145-ab34-784463b1acb9', '0c0db117-e641-4adc-856f-b517d6aa4bb2', NULL, 5, 'Servem com excelência e profissionalismo — esse eu indico.', 'Wesley Ramos', 'google', '2025-11-10 00:00:00.000', '2025-11-10 00:00:00.000'),
  ('f91404f5-9b65-40ba-b1f1-cfeec895621a', '0c0db117-e641-4adc-856f-b517d6aa4bb2', 'ef90c873-1483-4fd9-b7c9-b71c852e17c8', 5, 'Otimo', NULL, 'app', NULL, '2026-07-08 01:00:35.498');
