  ('site_content', '{"home":{"cta_title":"Tem uma empresa na cidade?","cta_button":"Anunciar grátis","hero_title":"Tudo sobre sua cidade num só app","cta_subtitle":"Cadastre-se grátis e apareça para quem mora em Vespasiano e São José da Lapa.","hero_overline":"App da Cidade","hero_subtitle":"Serviços públicos, telefones de emergência e o guia de empresas locais de Vespasiano e São José da Lapa."},"about":{"p1":"O AgendaAqui nasceu para conectar pessoas a empresas e profissionais de confiança em Vespasiano e São José da Lapa.","p2":"Aqui você encontra prestadores de serviços de construção civil, higienização, eventos e muito mais.","p3":"É grátis para usuários e grátis para começar a anunciar. Cadastre sua empresa em minutos.","title":"Sobre o AgendaAqui","subtitle":"Seu serviço certo, na hora certa."},"brand":{"name":"AgendaAqui","tagline":"Vespasiano · S. J. da Lapa"},"footer":{"location":"Minas Gerais, Brasil","biz_title":"Para empresas","copyright":"AgendaAqui. Todos os direitos reservados.","nav_title":"Navegação","about_text":"Tudo sobre sua cidade num só app. Serviços públicos, emergência e o guia de empresas de Vespasiano e São José da Lapa."},"header":{"cta_label":"Anunciar","admin_label":"Admin","login_label":"Entrar","panel_label":"Painel","logout_label":"Sair"},"contact":{"email":"contato@agendaaqui.online","title":"Fale com a gente","subtitle":"Sugestões, parcerias ou dúvidas? Estamos por aqui.","whatsapp_url":"https://wa.me/5531980252882","whatsapp_label":"Atendimento em horário comercial"},"newsletter":{"title":"Newsletter","description":"Receba dicas e novidades sobre serviços em MG.","button_label":"Assinar","name_placeholder":"Seu nome (opcional)","email_placeholder":"seu@email.com"}}', 1, '2026-07-10 09:17:22.503');
